#!/bin/bash
# TASK-5066 lab phase 2 (5 Gb/s): E0 health, E1 A/B, E2 AFE sweep coarse (1 load x 60 s per point)
cd /home/pi/ulx5m-serdes/t5066; export LOG=$PWD/log ME=TASK-5066 KEEP_LEASE=1; mkdir -p $LOG
T=/home/pi/ulx5m-serdes/tools
own=$(cat /home/pi/gs.owner 2>/dev/null); [ -n "$own" ] && [ "${own%% *}" != TASK-5066 ] && { echo "leased: $own"; exit 3; }
echo "TASK-5066 $(date +%s) SerDes 5G tuning (jelena) 5G E0/E1/E2" > /home/pi/gs.owner
echo "== E1 2.5G extra, interleaved $(date +%T)"
B=/home/pi/ulx5m-serdes/bitstreams
for k in 4 5 6; do
  LOG=$LOG/tmp_e1 $T/lab/abrun.sh $B/ber_gs_2g5_p1_CFGRST.bit $B/ber_m2_2g5_p1_txneg_CFGRST.bit 60 1 "e1_2g5_det1||" && mv $LOG/tmp_e1/e1_2g5_det1_r1.json $LOG/e1_2g5_det1_r$k.json
  LOG=$LOG/tmp_e1 $T/lab/abrun.sh gs_e1_2g5p1_s7.bit m2_e1_2g5p1_txneg_s1.bit 60 1 "e1_2g5_det0||" && mv $LOG/tmp_e1/e1_2g5_det0_r1.json $LOG/e1_2g5_det0_r$k.json
done
python3 $T/lab/ab_table.py $LOG/e1_2g5*_r*.json
echo "== E0 5G $(date +%T)"
fpga-jtag m2 m2_b0_5gp1_txneg_s1.bit -r 2>&1 | tail -1; fpga-jtag gs gs_b0_5gp1_txneg_s7.bit -r 2>&1 | tail -1; sleep 5
for b in gs m2; do fpga-jtag $b run python3 $T/eyescan.py health -n 10 --label "E0 5g p1" --out $LOG/e0_5g_$b.json 2>&1 | grep -v "^$"; done
echo "== E1 5G $(date +%T)"
$T/lab/abrun.sh gs_b0_5gp1_txneg_s7.bit m2_b0_5gp1_txneg_s1.bit 60 3 "e1_5g_det1||"
$T/lab/abrun.sh gs_e1_5gp1_txneg_s7.bit m2_e1_5gp1_txneg_s1.bit 60 3 "e1_5g_det0||"
echo "== E2 5G AFE $(date +%T)"
$T/lab/abrun.sh gs_e1_5gp1_txneg_s7.bit m2_e1_5gp1_txneg_s1.bit 60 1 "e2_g0_p24|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=24|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=24" "e2_g0_p24|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g0_p16|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=16|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=16" "e2_g0_p16|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g0_p12|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=12|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=12" "e2_g0_p12|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g0_p8|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=8|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=8" "e2_g0_p8|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g0_p4|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=4|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=4" "e2_g0_p4|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g0_p0|gs:RX_AFE_GAIN=0,RX_AFE_PEAK=0|m2:RX_AFE_GAIN=0,RX_AFE_PEAK=0" "e2_g0_p0|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p24|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=24|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=24" "e2_g1_p24|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p16|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=16|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=16" "e2_g1_p16|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p12|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=12|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=12" "e2_g1_p12|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p8|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=8|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=8" "e2_g1_p8|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p4|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=4|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=4" "e2_g1_p4|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g1_p0|gs:RX_AFE_GAIN=1,RX_AFE_PEAK=0|m2:RX_AFE_GAIN=1,RX_AFE_PEAK=0" "e2_g1_p0|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p24|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=24|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=24" "e2_g2_p24|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p16|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=16|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=16" "e2_g2_p16|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p12|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=12|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=12" "e2_g2_p12|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p8|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=8|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=8" "e2_g2_p8|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p4|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=4|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=4" "e2_g2_p4|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g2_p0|gs:RX_AFE_GAIN=2,RX_AFE_PEAK=0|m2:RX_AFE_GAIN=2,RX_AFE_PEAK=0" "e2_g2_p0|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p24|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=24|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=24" "e2_g3_p24|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p16|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=16|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=16" "e2_g3_p16|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p12|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=12|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=12" "e2_g3_p12|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p8|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=8|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=8" "e2_g3_p8|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p4|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=4|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=4" "e2_g3_p4|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK=" "e2_g3_p0|gs:RX_AFE_GAIN=3,RX_AFE_PEAK=0|m2:RX_AFE_GAIN=3,RX_AFE_PEAK=0" "e2_g3_p0|gs:RX_AFE_GAIN=,RX_AFE_PEAK=|m2:RX_AFE_GAIN=,RX_AFE_PEAK="
python3 $T/lab/ab_table.py $LOG/e1_5g*_r*.json $LOG/e2_*_r*.json
rm -f /home/pi/gs.owner; echo "LAB2 DONE $(date +%T)"
